import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        k = int(next(iterator))

        # If package size can be n (i.e., k >= n), we buy 1 package of size n.
        if k >= n:
            results.append(1)
        else:
            # We need to find the smallest x such that there exists a package size s (1 <= s <= k)
            # where n is divisible by s. Then the number of packages is n // s.
            # This is equivalent to finding the largest divisor of n that is <= k.
            # Let that divisor be d. Then answer = n // d.
            # To minimize n // d, we maximize d.

            # Since k < n, d must be a proper divisor of n.
            # We iterate from 1 up to sqrt(n) to find divisors.
            # We want the largest divisor <= k.

            best_d = 1
            limit = int(n ** 0.5)

            for i in range(1, limit + 1):
                if n % i == 0:
                    d1 = i
                    d2 = n // i

                    if d1 <= k:
                        if d1 > best_d:
                            best_d = d1
                    if d2 <= k:
                        if d2 > best_d:
                            best_d = d2

            # The number of packages is n // best_d
            results.append(n // best_d)

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
